package com.macdmr.radio;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;

public class P8ChannelCsvTest {
    private ChannelCsv.Row fm(){ChannelCsv.Row r=new ChannelCsv.Row();r.channel=new ChannelStore.Channel();r.channel.type=1;r.channel.name="Local";r.channel.rxFreq=446106251;r.channel.txFreq=446106250;r.channel.rxOnly=true;return r;}
    private String valid(){return ChannelCsv.write(Collections.singletonList(fm()));}
    private void invalid(String text,String expected){try{ChannelCsv.Parsed p=ChannelCsv.parse(text);assertFalse(p.valid());assertTrue(p.errors.toString(),p.errors.toString().contains(expected));}catch(IllegalArgumentException e){assertTrue(e.getMessage(),e.getMessage().contains(expected));}}
    @Test public void exactHzAndExcelScientificNotation(){assertEquals(446106250,ChannelCsv.frequency("446.10625"));assertEquals(446106251,ChannelCsv.frequency("446.106251"));assertEquals(446106250,ChannelCsv.frequency("4.4610625E2"));for(String s:new String[]{"446.1062501","NaN","Infinity","999999999","1e100","446,10625","175"})try{ChannelCsv.frequency(s);fail(s);}catch(IllegalArgumentException expected){}}
    @Test public void fmRoundTripRetainsQuotesUnicodeNewlinesAndEscapedMembership(){ChannelCsv.Row r=fm();r.channel.name="Café, \"Local\"";r.channel.notes="Line one\r\nLine two, \"quoted\"";r.zones=Arrays.asList("One|Two","Path\\Zone");r.scanLists=Arrays.asList("Mix, 1");String text=ChannelCsv.write(Arrays.asList(r));assertTrue(text.startsWith("\uFEFF"+ChannelCsv.HEADER+"\r\n"));ChannelCsv.Parsed p=ChannelCsv.parse(text);assertTrue(p.errors.toString(),p.valid());ChannelCsv.Row n=p.rows.get(0);assertEquals(r.channel.name,n.channel.name);assertEquals(r.channel.notes,n.channel.notes);assertEquals(r.zones,n.zones);assertEquals(r.scanLists,n.scanLists);assertEquals(446106251,n.channel.rxFreq);assertEquals(446106250,n.channel.txFreq);assertEquals(text,ChannelCsv.write(p.rows));}
    @Test public void dmrAndToneSettingsRoundTrip(){ChannelCsv.Parsed p=ChannelCsv.parse(ChannelCsv.template(true));assertTrue(p.valid());ChannelCsv.Row r=p.rows.get(1);r.channel.rxType=1;r.channel.rxSubCode=13;r.channel.txType=3;r.channel.txSubCode=0;r.channel.cc=15;r.channel.inSlot=1;r.channel.outSlot=0;r.channel.txContact=123456;r.channel.contactType=0;r.channel.groups=new int[]{9,1234};r.channel.mode=4;r.channel.softSq=true;r.channel.softSqLevel=10;ChannelStore.Channel c=ChannelCsv.parse(ChannelCsv.write(Arrays.asList(r))).rows.get(0).channel;assertEquals(0,c.type);assertEquals(15,c.cc);assertEquals(1,c.inSlot);assertEquals(0,c.outSlot);assertEquals(123456,c.txContact);assertEquals(0,c.contactType);assertArrayEquals(r.channel.groups,c.groups);assertEquals(4,c.mode);assertEquals(1,c.rxType);assertEquals(13,c.rxSubCode);assertEquals(3,c.txType);assertEquals(0,c.txSubCode);assertTrue(c.softSq);assertEquals(10,c.softSqLevel);}
    @Test public void rejectsBadRowsWithLineNumbers(){invalid(valid().replace("446.106251","oops"),"Line 2");invalid(valid().replace("\"Low\"","\"Maximum\""),"power");invalid(valid().replace("\"None\"","\"CTCSS 999\""),"Invalid tone");invalid(valid().replace("\"true\"","\"maybe\""),"receive_only");invalid(valid().replace("\"25\"","\"50\""),"bandwidth");}
    @Test public void malformedCsvNeverReturnsPartialSuccess(){invalid(valid()+"\"unclosed","unclosed");invalid(valid().replace("\"Local\"","Lo\"cal"),"quote");invalid(valid().replace("\"Local\"","\"Local\"junk"),"closing quote");invalid(valid()+valid().substring(valid().indexOf('\n')+1),"Repeated channel name");}
    @Test public void requiresVersionAndExactHeaderButAcceptsReorderedColumns(){invalid(valid().replace("\"1\",\"Local\"","\"2\",\"Local\""),"format_version");invalid(valid().replace("rx_mhz","other"),"header");invalid(valid().replace("tx_mhz","rx_mhz"),"Duplicate column");String text=valid();String[] lines=text.substring(1).split("\r\n");String[] h=lines[0].split(","),cells=lines[1].split(",",-1);Collections.reverse(Arrays.asList(h));Collections.reverse(Arrays.asList(cells));assertTrue(ChannelCsv.parse(String.join(",",h)+"\n"+String.join(",",cells)).valid());}
    @Test public void blanksLimitsAndUnsupportedModes(){invalid(ChannelCsv.template(false),"No channel rows");invalid("","empty");invalid(new String(new char[ChannelCsv.MAX_CHARS+1]).replace('\0','x'),"2 MB");ChannelCsv.Row r=fm();r.channel.type=2;try{ChannelCsv.write(Arrays.asList(r));fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("FM/DMR"));}r.channel.type=0;r.channel.encryptSw=1;try{ChannelCsv.write(Arrays.asList(r));fail();}catch(IllegalArgumentException expected){assertTrue(expected.getMessage().contains("encrypted"));}}
    @Test public void examplesAreReceiveOnlyAndUseStandardSchema(){ChannelCsv.Parsed p=ChannelCsv.parse(ChannelCsv.template(true));assertTrue(p.errors.toString(),p.valid());assertEquals(2,p.rows.size());for(ChannelCsv.Row r:p.rows)assertTrue(r.channel.rxOnly);assertEquals(p.rows.get(0).scanLists,p.rows.get(1).scanLists);assertEquals(25,ChannelCsv.HEADER.split(",").length);}
}
